"use client";

import { Search, Filter, ChevronDown } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { useEffect, useState, useCallback, useRef } from "react";
import { getMoviesClient, searchMoviesClient, getVJsClient, getMoviesByVJClient } from "@/lib/api-client";
import { NetflixCard } from "@/components/NetflixCard";

type Movie = {
  id: string;
  title: string;
  description?: string;
  thumbnail_url?: string;
  cover_image_url?: string;
  poster_path?: string;
  backdrop_path?: string;
  vjs?: { id: string; name: string };
  genre_ids?: string[];
  genres?: string[];
  release_date?: string;
  [key: string]: any;
};

type VJ = {
  id: string;
  name: string;
};

export default function MoviesClient() {
  const [movies, setMovies] = useState<Movie[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedGenre, setSelectedGenre] = useState("");
  const [selectedVj, setSelectedVj] = useState("");
  const [selectedYear, setSelectedYear] = useState("");
  const [vjs, setVjs] = useState<VJ[]>([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);

  // Fetch initial movies and VJs
  useEffect(() => {
    async function init() {
      setLoading(true);
      try {
        const [moviesRes, vjsRes] = await Promise.all([
          getMoviesClient(1, 30),
          getVJsClient(),
        ]);
        setMovies(moviesRes.data || []);
        setHasMore(moviesRes.hasMore);
        setVjs(vjsRes || []);
      } catch (err) {
        console.error("Error loading movies:", err);
      } finally {
        setLoading(false);
      }
    }
    init();
  }, []);

  // Handle Search & Filter changes
  useEffect(() => {
    async function filterMovies() {
      setLoading(true);
      setPage(1);
      try {
        if (searchTerm.trim()) {
          const results = await searchMoviesClient(searchTerm);
          setMovies(results || []);
          setHasMore(false);
        } else if (selectedVj) {
          const vjName = vjs.find((v) => v.id === selectedVj)?.name || selectedVj;
          const results = await getMoviesByVJClient(selectedVj, vjName);
          setMovies(results || []);
          setHasMore(false);
        } else {
          const results = await getMoviesClient(1, 30);
          setMovies(results.data || []);
          setHasMore(results.hasMore);
        }
      } catch (err) {
        console.error("Error filtering movies:", err);
      } finally {
        setLoading(false);
      }
    }

    const timer = setTimeout(() => {
      filterMovies();
    }, 300);

    return () => clearTimeout(timer);
  }, [searchTerm, selectedVj, vjs]);

  // Load more pagination
  const handleLoadMore = async () => {
    if (loadingMore || !hasMore) return;
    setLoadingMore(true);
    const nextPage = page + 1;
    try {
      const moreMovies = await getMoviesClient(nextPage, 30);
      if (moreMovies.data && moreMovies.data.length > 0) {
        setMovies((prev) => [...prev, ...moreMovies.data]);
        setHasMore(moreMovies.hasMore);
        setPage(nextPage);
      } else {
        setHasMore(false);
      }
    } catch (err) {
      console.error("Error loading more:", err);
    } finally {
      setLoadingMore(false);
    }
  };

  return (
    <div className="min-h-screen bg-black text-white px-4 md:px-12 py-8">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl md:text-5xl font-black mb-3">
          Luganda Translated Movies
        </h1>
        <p className="text-gray-400 max-w-2xl text-sm md:text-base">
          Browse and stream the complete collection of Luganda translated movies by Uganda&apos;s finest Video Jockeys (VJs) — VJ Junior, Omutaka Ice P, VJ Jingo, VJ Emmy, and more.
        </p>
      </div>

      {/* Filters Bar */}
      <div className="flex flex-col md:flex-row gap-4 mb-8 bg-gray-900/80 p-4 rounded-xl border border-gray-800">
        {/* Search */}
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
          <input
            type="text"
            placeholder="Search movies by title, actor, or keyword..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-black border border-gray-700 rounded-lg text-white placeholder-gray-500 focus:outline-none focus:border-orange-500 text-sm"
          />
        </div>

        {/* VJ Filter */}
        <div className="w-full md:w-56">
          <select
            value={selectedVj}
            onChange={(e) => setSelectedVj(e.target.value)}
            className="w-full py-2.5 px-3 bg-black border border-gray-700 rounded-lg text-white text-sm focus:outline-none focus:border-orange-500"
          >
            <option value="">All VJs (Translators)</option>
            {vjs.map((vj) => (
              <option key={vj.id} value={vj.id}>
                {vj.name}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Content Grid */}
      {loading ? (
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-4">
          {Array.from({ length: 18 }).map((_, i) => (
            <div
              key={i}
              className="aspect-[2/3] rounded-lg bg-gray-900 animate-pulse border border-gray-800"
            />
          ))}
        </div>
      ) : movies.length > 0 ? (
        <>
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-4">
            {movies.map((movie) => (
              <NetflixCard key={movie.id} content={movie} type="movie" />
            ))}
          </div>

          {hasMore && !searchTerm && !selectedVj && (
            <div className="text-center mt-12 mb-8">
              <Button
                onClick={handleLoadMore}
                disabled={loadingMore}
                className="bg-orange-500 hover:bg-orange-600 text-white px-8 py-3 rounded-lg font-semibold transition"
              >
                {loadingMore ? "Loading more movies..." : "Load More Movies"}
              </Button>
            </div>
          )}
        </>
      ) : (
        <div className="text-center py-20 bg-gray-950 rounded-2xl border border-gray-900">
          <p className="text-gray-400 text-lg mb-4">No movies found matching your search.</p>
          <Button
            onClick={() => {
              setSearchTerm("");
              setSelectedVj("");
            }}
            className="bg-orange-500 hover:bg-orange-600 text-white"
          >
            Clear Filters
          </Button>
        </div>
      )}
    </div>
  );
}
