import Link from "next/link";
import Image from "next/image";
import { Movie, Series } from "@/lib/supabase";

// Netflix-style card component for both movies and series
type TMDBGenreMovie = {
  id: number | string;
  title?: string;
  poster_url?: string;
  cover_url?: string;
  description?: string;
  release_date?: string;
  thumbnail_url?: string;
  cover_image_url?: string;
};

type NetflixCardProps = {
  content: Movie | Series | TMDBGenreMovie;
  type: "movie" | "series";
  isNonTranslated?: boolean;
};

export const NetflixCard = ({ content, type, isNonTranslated = false }: NetflixCardProps) => {
  const getHref = () => {
    if (isNonTranslated) {
      return `/non-translated/${type === "movie" ? "movies" : "series"}/${content.id}`;
    }
    return `/${type === "movie" ? "movies" : "series"}/${content.id}`;
  };

  // Extract VJ Name comprehensively across all possible object shapes
  const getVjName = (): string | null => {
    if (!content) return null;
    if ('vjs' in content && content.vjs) {
      if (typeof content.vjs === 'string' && content.vjs) return content.vjs;
      if (typeof (content.vjs as any).name === 'string' && (content.vjs as any).name) return (content.vjs as any).name;
    }
    if ('vj_name' in content && typeof (content as any).vj_name === 'string' && (content as any).vj_name) {
      return (content as any).vj_name;
    }
    if ('vj' in content && (content as any).vj) {
      if (typeof (content as any).vj === 'string' && (content as any).vj) return (content as any).vj;
      if (typeof (content as any).vj.name === 'string' && (content as any).vj.name) return (content as any).vj.name;
    }
    if ('translator' in content && typeof (content as any).translator === 'string' && (content as any).translator) {
      return (content as any).translator;
    }
    return null;
  };

  const vjName = getVjName();

  // Get the best available image URL with type safety
  const getImageUrl = (): string => {
    return content.thumbnail_url ||
      content.cover_image_url ||
      (('poster_url' in content && content.poster_url) ? content.poster_url as string : '') ||
      (('poster_path' in content && content.poster_path) ? content.poster_path as string : '') ||
      (('backdrop_path' in content && content.backdrop_path) ? content.backdrop_path as string : '') ||
      `https://via.placeholder.com/240x360/1f2937/f97316?text=${encodeURIComponent(content.title || '')}`;
  };

  return (
    <div className="group">
      <Link href={getHref()}>
        <div className="cursor-pointer transition-transform duration-200 hover:scale-105">
          <div className="aspect-[2/3] relative rounded-lg overflow-hidden bg-gray-800 mb-2">
            <Image
              src={getImageUrl()}
              alt={content.title || `Poster for ${type}`}
              fill
              className="object-cover transition-opacity duration-300"
              unoptimized
              onError={(e) => {
                const target = e.target as HTMLImageElement;
                target.src = `https://via.placeholder.com/240x360/1f2937/f97316?text=${encodeURIComponent(content.title || '')}`;
              }}
            />

            {/* Content type badge - top left */}
            <div className={`absolute top-1 left-1 px-1.5 py-0.5 rounded text-[10px] font-bold ${type === "movie" ? "bg-[#FF7F50]" : "bg-[#1ABC9C]"
              }`}>
              {type === "movie" ? "Movie" : "Series"}
            </div>

            {/* VJ Tag - High Visibility Vibrant Orange Badge at Bottom Right */}
            {vjName && (
              <div className="absolute bottom-1 right-1 bg-black/85 backdrop-blur-md border border-orange-500/60 px-1.5 py-0.5 rounded shadow-[0_0_12px_rgba(249,115,22,0.35)] flex items-center z-10">
                <span className="text-orange-400 font-bold text-[10px] sm:text-[11px] truncate max-w-[85px] md:max-w-[110px] tracking-wide">
                  {vjName}
                </span>
              </div>
            )}

            {/* Description overlay on hover - simplified */}
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all duration-300 flex flex-col justify-end p-2">
              <p className="text-[10px] text-gray-300 line-clamp-2 leading-tight">
                {(typeof (content as any).overview === 'string' && (content as any).overview
                  ? (content as any).overview.slice(0, 40)
                  : content.description?.slice(0, 40)) + '...' || 'Tap to view details'}
              </p>
            </div>
          </div>
        </div>
      </Link>

      {/* Content info outside the card - more compact */}
      <div className="mt-1">
        <h3 className="font-medium text-white text-xs truncate leading-tight">{content.title}</h3>
        <div className="flex items-center gap-1 text-[10px] text-gray-400 mt-0.5">
          {content.release_date && (
            <span>{new Date(content.release_date).getFullYear()}</span>
          )}
          {('genre_ids' in content && Array.isArray(content.genre_ids) && content.genre_ids.length > 0) && (
            <>
              <span>•</span>
              <span className="text-gray-400 capitalize truncate max-w-[90px]">
                {content.genre_ids.slice(0, 2).join(', ')}
              </span>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

